"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5762],{22461:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"HttpStore","desc":"Saves and loads replays through a plain HTTP backend. The server contract:\\n\\n- `GET    <base>`         \u2192 JSON array of keys\\n- `GET    <base>/<key>`   \u2192 raw replay bytes (404 when missing)\\n- `PUT    <base>/<key>`   \u2192 stores the raw body\\n- `DELETE <base>/<key>`   \u2192 removes the replay\\n\\nAn optional bearer token is sent as `Authorization: Bearer <token>`.\\nRequires HttpService to be enabled and runs on the server or in Studio.","source":{"line":14,"path":"packages/src/Flashback/HttpStore.luau"}}')}}]);